import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { Search, Leaf, MapPin } from "lucide-react";
import {
  getAllSchemes,
  getByCategory,
  getByState
} from "../services/schemeService";

const SchemePage = () => {

  const [schemes, setSchemes] = useState([]);
  const [search, setSearch] = useState("");
  const [lang, setLang] = useState(localStorage.getItem("lang") || "en");

  useEffect(() => {
    fetchSchemes();
  }, [lang]);

  const fetchSchemes = async () => {
    const data = await getAllSchemes(lang);
    setSchemes(data);
  };

  const changeLanguage = (newLang) => {
    localStorage.setItem("lang", newLang);
    setLang(newLang);
  };

  const filteredSchemes = schemes.filter((s) =>
    s.schemeName.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="container">

      <h2 className="main-heading">
        <Leaf /> 🌾 Farmer Schemes
      </h2>

      {/* 🌐 Language */}
      <div className="lang-switch">
        <button onClick={() => changeLanguage("en")}>EN</button>
        <button onClick={() => changeLanguage("hi")}>हिंदी</button>
        <button onClick={() => changeLanguage("mr")}>मराठी</button>
      </div>

      {/* 🔍 Search */}
      <div className="search-box">
        <Search />
        <input
          placeholder="Search (उदा: subsidy, कर्ज)..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* 🧱 Cards */}
      <div className="grid">
        {filteredSchemes.map((scheme) => (
          <div key={scheme.id} className="card">

            <img src={scheme.image} alt={scheme.schemeName} />

            <div className="card-body">

              <h3>{scheme.schemeName}</h3>

              <p className="state">
                <MapPin size={16}/> {scheme.state}
              </p>

              {/* 🔥 Quick Info */}
              <div className="badges">
                <span>💰 {scheme.benefits?.substring(0,20)}...</span>
                <span>📄 Easy Apply</span>
              </div>

              <Link to={`/scheme/${scheme.id}`} className="btn">
                Apply Now 🚀
              </Link>

            </div>
          </div>
        ))}
      </div>

    </div>
  );
};

export default SchemePage;
